def to_sql(spec):
    sql = f"SELECT {', '.join(spec['select'])} FROM {spec['table']}"
    if spec.get("where"):
        sql += f" WHERE {spec['where']}"
    if spec.get("group_by"):
        sql += f" GROUP BY {', '.join(spec['group_by'])}"
    if spec.get("order_by"):
        sql += f" ORDER BY {spec['order_by']}"
    return sql

print(to_sql({"table": "orders", "select": ["category", "SUM(amount) AS total"], "where": "amount >= 20", "group_by": ["category"], "order_by": "total DESC"}))
print(to_sql({"table": "orders", "select": ["order_id", "amount"], "where": None, "group_by": None, "order_by": None}))
